select psi.id, psi.code, psi.purchase_order_code, psi.supplier_name, psi.approve_status, psi.invalid_status, psid.sku_id, psid.sku_no, psi.stock_in_date, psi.purchase_user_name, psi.stock_in_user_name, psi.approve_user_name, psi.create_user_name, psi.create_time, psid.purchase_qty, psid.receive_qty, psid.stock_in_qty, psid.exceed_qty, psi.delivery_warehouse_name, psid.remark from purchase_stock_in psi inner join purchase_stock_in_detail psid on psi.id = psid.main_id and psid.is_deleted = false
